private class Frequency {
	private long _threshold;
	private double _multiplier;

	private Frequency(long threshold, double multiplier) {
		_threshold = threshold;
		_multiplier = multiplier;
	}

	boolean exceeded(long timestamp) {
		return timestamp > _threshold;
	}

	void adjust(long timestamp) {
		if (timestamp < _threshold) {
			return;
		}

		long delta = timestamp - _threshold;
		_threshold += Math.ceil(delta * _multiplier);

		if (_threshold < INITIAL_FREQUENCY_THRESHOLD) {
			_threshold = INITIAL_FREQUENCY_THRESHOLD;
		}
	}
}

