protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the number of ranges required to split the time range
    int numRanges = (int) (end - start) / FETCH_DATA_DURATION;

    // Add the time ranges to the list
    for (int i = 0; i < numRanges; i++) {
        long startTime = start + (i * FETCH_DATA_DURATION);
        long endTime = start + ((i + 1) * FETCH_DATA_DURATION);
        timeRanges.add(new TimeRange(startTime, endTime));
    }

    // Add a final range to include any remaining time after the last split
    if (timeRanges.size() > 0) {
        long startTime = timeRanges.get(timeRanges.size() - 1).getEnd();
        long endTime = end;
        timeRanges.add(new TimeRange(startTime, endTime));
    }

    return timeRanges;
}
