    // Default is WebRequestImpl. However, this can be changed if needed.
    AtmosphereRequest atmosphereRequest = AtmosphereRequestFactory.get().getInstance("WebRequestImpl");

    // We set the HTTP method to the one we initially received.
    // This is important, as the AtmosphereRequest may use this param to determine the action.
    atmosphereRequest.setMethod(method);

    // Then add any properties that are not being passed as params
    // That we may have previously set.
    atmosphereRequest.setFilteredResourcePath(req.ggetRequestURI());
    atmosphereRequest.setMatchOnUriPrefix(true);

    // And finally, we add the request object into the AtmosphereRequest.
    // This is where the connection to the actual request is made.
    atmosphereRequest.setRequest(req);

    // Return the finished AtmosphereRequest object.
    return atmosphereRequest;
}

