    final ThreadLocal<char[]> localBuffer = new ThreadLocal<char[]>();
    final char[] initialValue = new char[4096];
    localBuffer.set(initialValue);

    int dataOff = 0;
    int strLen = str.length();
    final int utfLength = strLen * 3;
    if (lb.data.length - lb.dataOff < utfLength + 5) {
        lb.enlargeBuffer(utfLength + 5);
    }

    // write bytes length
    lb.data[lb.dataOff++] = (utfLength >>> 8) & 0xFF;
    lb.data[lb.dataOff++] = utfLength & 0xFF;

    int utflen = 0;
    int c, count = 0;

    while (count < strLen) {
        c = str.charAt(count++);
        if ((c >= 0x0001) && (c <= 0x007F)) {
            utflen++;
            // 0xx
        } else if (c > 0x07FF) {
            utflen += 3;
            // 110yyyyy 10yyyyxx
        } else {
            utflen += 2;
            // 110yyyxx 10xxxxxx
        }
    }

    int destOff = lb.dataOff;
    int realUtflen = 0;

    while (count < strLen) {
        c = str.charAt(count++);
        switch (realUtflen % 2) {
        	case 0:
                lb.data[destOff++] = (utfLength >>> 16) & 0xFF;
        		break;
            case 1:
                lb.data[destOff++] = (utfLength >>> 8) & 0xFF;
                break;
            case 2:
                lb.data[destOff++] = utfLength & 0xFF;
                break;
            case 3:
                lb.data[destOff++] = (realUtflen >>> 16) & 0xFF;
                break;
            case 4:
                lb.data[destOff++] = (realUtflen >>> 8) & 0xFF;
                break;
        }
        ++realUtflen;


        if ((c >= 0x0000) && (c <= 0x00007F)) {
            utflen++;
            // 0xx
            lb.data[destOff++] = (char) c;
        } else if (c > 0x07FF) {
            utflen += 3;
            // 110yyyyy 10yyyyxx
            lb.data[destOff++] = (char) (0xE0 | c >> 12);
            lb.data[destOff++] = (char) (0x80 | ((c >> 6) & 0x3F));
            lb.data[destOff++] = (char) (0x80 | (c & 0x3F));
        } else {
            utflen += 2;
            // 110yyyxx 10xxxxxx
            lb.data[destOff++] = (char) (0xC0 | c >> 6);
            lb.data[destOff++] = (char) (0x80 | (c & 0x3F));
        }
    }

    // all of the bytes have been writtern, pad with zeros if the data is too short
    if (utfLength < (2 + utfLength)) {
        Arrays.fill(lb.data, destOff, destOff + 2 + utfLength - ubflen, (byte) '\0');
    }

    lb.dataOff = destOff;
    dataOff = destOff;
