        int visibleRows = table.getVisibleRowCount();
        int totalRows = table.getRowCount();
        int extent = visibleRows * rowHeight;

        model.setExtent(extent);
        model.setMaximum(totalRows * rowHeight);
        model.setMinimum(0);
        model.setValue(table.getRowCount() * rowHeight);
