// Function to build the Content-Range HTTP header value
String buildContentRange() {
    // Calculate the Content-Range value based on the resource length and offset
    int contentLength = resource.getLength();
    int offset = request.getOffset();
    int rangeLength = request.getRangeLength();

    if (contentLength == -1) {
        // If the resource length is unknown, set the Content-Range value to 'bytes */*'
        return "bytes */*";
    } else {
        // Otherwise, set the Content-Range value to 'bytes X-Y/Z'
        return "bytes " + (offset + 1) + "-" + (offset + rangeLength) + "/" + contentLength + "";
    }
}

