private static ThreadSnapshot parseThreadSnapshotFromLine(String line) {
    String[] parts = line.split(",");
    if (parts.length >= 2) {
        long timestamp = Long.parseLong(parts[0]);
        Set<String> threadNames = new HashSet<>();
        for (int i = 1; i < parts.length; i++) {
            threadNames.add(parts[i]);
        }
        return new ThreadSnapshot(timestamp, threadNames);
    }
    return null;
}

